"use client";

import {
  memo,
  useEffect,
  useId,
  useImperativeHandle,
  useState,
  useContext,
  type ReactNode,
} from "react";
import { Send } from "lucide-react";
import { cn } from "@/lib/utils";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { useAutosizeTextarea } from "../hooks/use-autosize-textarea";
import { CommentThreadContext } from "./thread-context";
import {
  defaultCommentThreadLabels,
  type CommentThreadCurrentUser,
  type CommentThreadLabels,
} from "../types";

export interface CommentComposerProps {
  currentUser?: CommentThreadCurrentUser;
  /** Defaults to labels.composerPlaceholder. */
  placeholder?: string;
  /** Initial uncontrolled value. */
  initialValue?: string;
  /** Controlled value — pair with onChange. */
  value?: string;
  onChange?: (next: string) => void;
  /**
   * Required when used standalone. A rejected promise keeps the text, shows `labels.postFailed`
   * (`role="alert"`) and calls `onError`; it never escapes the composer.
   */
  onSubmit: (content: string) => Promise<void> | void;
  /** Called with the error when `onSubmit` rejects (or throws). */
  onError?: (error: unknown) => void;
  /** Optional Cancel button — only renders when provided. */
  onCancel?: () => void;
  /** Force-disable the composer (sign-out / network down). */
  disabled?: boolean;
  /** External busy signal — overrides internal isSubmitting. */
  isSubmitting?: boolean;
  /** Default true. */
  submitOnEnter?: boolean;
  /** Defaults: 1 / 6. */
  minRows?: number;
  maxRows?: number;
  /** Aria-label override on the textarea. */
  ariaLabel?: string;
  /** Override the avatar visual entirely (e.g. persona switcher). */
  avatarSlot?: ReactNode;
  /** Auto-focus on mount (use for inline reply composers). */
  autoFocus?: boolean;
  /** 0.6.0. `"touch"`: Send and Cancel have a hit area of at least 44 × 44 px. Default `"default"`. */
  size?: "default" | "touch";
  className?: string;
  /** Classes for the failure alert. */
  errorClassName?: string;
  labels?: Pick<
    CommentThreadLabels,
    "composerPlaceholder" | "composerSend" | "composerCancel" | "postFailed"
  >;
  ref?: React.Ref<CommentComposerHandle>;
}

export interface CommentComposerHandle {
  focus: () => void;
  blur: () => void;
  clear: () => void;
}

function initials(name: string, locale: string): string {
  return name
    .trim()
    .split(/\s+/)
    .map((part) => (part[0] ? part[0].toLocaleUpperCase(locale) : ""))
    .slice(0, 2)
    .join("") || "?";
}

function CommentComposerInner({
  currentUser,
  placeholder,
  initialValue = "",
  value: controlledValue,
  onChange,
  onSubmit,
  onError,
  onCancel,
  disabled = false,
  isSubmitting: controlledSubmitting,
  submitOnEnter = true,
  minRows = 1,
  maxRows = 6,
  ariaLabel,
  avatarSlot,
  autoFocus = false,
  size = "default",
  className,
  errorClassName,
  labels,
  ref,
}: CommentComposerProps) {
  // Inside a thread: its locale (no new prop on the composer). Standalone: "en".
  const threadLocale = useContext(CommentThreadContext)?.locale ?? "en";
  const isValueControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = useState(initialValue);
  const value = isValueControlled ? controlledValue : internalValue;

  const isSubmittingControlled = controlledSubmitting !== undefined;
  const [internalSubmitting, setInternalSubmitting] = useState(false);
  const isSubmitting = isSubmittingControlled
    ? controlledSubmitting
    : internalSubmitting;

  const [hasError, setHasError] = useState(false);
  // A controlled value replaced from outside (a prefill) is a new draft: the old failure no
  // longer describes it. The echo of the user's own typing already clears the error.
  const [typed, setTyped] = useState<string | null>(null);
  const [seenValue, setSeenValue] = useState(controlledValue);
  if (isValueControlled && controlledValue !== seenValue) {
    setSeenValue(controlledValue);
    if (controlledValue !== typed) setHasError(false);
  }
  const errorId = useId();

  const textareaRef = useAutosizeTextarea(value, { minRows, maxRows });

  // Auto-focus on mount for inline reply composers (effect runs once).
  useEffect(() => {
    if (autoFocus) textareaRef.current?.focus();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useImperativeHandle(
    ref,
    () => ({
      focus: () => textareaRef.current?.focus(),
      blur: () => textareaRef.current?.blur(),
      clear: () => {
        if (!isValueControlled) setInternalValue("");
        setHasError(false);
        onChange?.("");
      },
    }),
    // textareaRef identity is stable; setters are stable; onChange may change but
    // that's OK — the imperative handle reads it via closure on call.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [isValueControlled, onChange],
  );

  const submit = async () => {
    const trimmed = value.trim();
    if (!trimmed || isSubmitting || disabled) return;
    if (!isSubmittingControlled) setInternalSubmitting(true);
    try {
      await onSubmit(trimmed);
      setHasError(false);
      if (!isValueControlled) setInternalValue("");
      onChange?.("");
    } catch (error) {
      // Keep the text so the user can try again; the failure is shown, never thrown.
      setHasError(true);
      onError?.(error);
    } finally {
      if (!isSubmittingControlled) setInternalSubmitting(false);
    }
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // Enter / Escape during IME composition belong to the input method (keyCode 229 on older engines).
    if (e.nativeEvent.isComposing || e.keyCode === 229) return;
    if (submitOnEnter && e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      void submit();
      return;
    }
    if (e.key === "Escape" && onCancel) {
      e.preventDefault();
      onCancel();
    }
  };

  const placeholderText =
    placeholder ?? labels?.composerPlaceholder ?? defaultCommentThreadLabels.composerPlaceholder;
  const sendLabel = labels?.composerSend ?? defaultCommentThreadLabels.composerSend;
  const cancelLabel = labels?.composerCancel ?? defaultCommentThreadLabels.composerCancel;
  const failedLabel = labels?.postFailed ?? defaultCommentThreadLabels.postFailed;
  const touch = size === "touch";
  const sendBlocked = !value.trim() || isSubmitting || disabled;

  return (
    <div className={cn("flex items-start gap-2", className)}>
      {avatarSlot ??
        (currentUser ? (
          <Avatar className="h-8 w-8 shrink-0">
            {currentUser.avatar ? (
              <AvatarImage src={currentUser.avatar} alt="" />
            ) : null}
            <AvatarFallback>{initials(currentUser.name, threadLocale)}</AvatarFallback>
          </Avatar>
        ) : null)}
      <div className="relative flex-1">
        <Textarea
          ref={textareaRef}
          value={value}
          onChange={(e) => {
            if (!isValueControlled) setInternalValue(e.target.value);
            setHasError(false);
            setTyped(e.target.value);
            onChange?.(e.target.value);
          }}
          onKeyDown={onKeyDown}
          placeholder={placeholderText}
          rows={minRows}
          disabled={disabled}
          readOnly={isSubmitting}
          aria-label={ariaLabel ?? placeholderText}
          aria-busy={isSubmitting}
          aria-invalid={hasError || undefined}
          aria-describedby={hasError ? errorId : undefined}
          // Touch: at least 44 px tall so the absolutely placed 44 px Send (top-0) stays inside the field.
          className={cn("resize-none border-0 bg-muted/50", touch ? "min-h-11 pe-12" : "pe-10")}
        />
        <Button
          type="button"
          variant="ghost"
          size="icon"
          onClick={() => {
            void submit();
          }}
          // aria-disabled, not disabled: a focused Send that turns disabled drops focus to <body>.
          aria-disabled={sendBlocked || undefined}
          disabled={disabled}
          aria-label={sendLabel}
          className={cn(
            "absolute end-1 aria-disabled:pointer-events-none aria-disabled:opacity-50",
            touch ? "top-0 min-h-11 min-w-11" : "top-1.5 h-7 w-7",
          )}
        >
          <Send
            className={cn(
              "h-4 w-4",
              value.trim() && "text-primary",
            )}
          />
        </Button>
        {hasError ? (
          <p
            id={errorId}
            role="alert"
            className={cn("mt-1 text-xs text-destructive", errorClassName)}
          >
            {failedLabel}
          </p>
        ) : null}
      </div>
      {onCancel ? (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={() => {
            if (!isValueControlled) setInternalValue("");
            onChange?.("");
            onCancel();
          }}
          disabled={isSubmitting}
          className={touch ? "min-h-11 min-w-11" : undefined}
        >
          {cancelLabel}
        </Button>
      ) : null}
    </div>
  );
}

