"use client";

import { useEffect, useReducer, useRef } from "react";
import type {
  Comment,
  CommentDelta,
  CommentLocalAction,
  Subscribe,
} from "../types";
import { containsId, hasClientId } from "../lib/tree";

// ─── Pure tree-walk helpers ──────────────────────────────────────────────────

function findAndPatch(
  tree: Comment[],
  predicate: (c: Comment) => boolean,
  patch: (c: Comment) => Comment,
): Comment[] {
  let mutated = false;
  const next = tree.map((c) => {
    if (predicate(c)) {
      const patched = patch(c);
      if (patched !== c) mutated = true;
      return patched;
    }
    if (c.replies && c.replies.length > 0) {
      const replies = findAndPatch(c.replies, predicate, patch);
      if (replies !== c.replies) {
        mutated = true;
        return { ...c, replies };
      }
    }
    return c;
  });
  return mutated ? next : tree;
}

function pruneById(tree: Comment[], id: string): Comment[] {
  let mutated = false;
  const next: Comment[] = [];
  for (const c of tree) {
    if (c.id === id) {
      mutated = true;
      continue;
    }
    if (c.replies && c.replies.length > 0) {
      const replies = pruneById(c.replies, id);
      if (replies !== c.replies) {
        mutated = true;
        const removed = c.replies.length - replies.length;
        next.push({
          ...c,
          replies,
          ...(c.replyCount !== undefined && removed > 0
            ? { replyCount: Math.max(replies.length, c.replyCount - removed) }
            : {}),
        });
        continue;
      }
    }
    next.push(c);
  }
  return mutated ? next : tree;
}

/** A parent's `replyCount` (when it has one) after its replies grew by `added`: never below what is loaded. */
function withReplyCount(c: Comment, replies: Comment[], added: number): Comment {
  return {
    ...c,
    replies,
    ...(c.replyCount !== undefined
      ? { replyCount: Math.max(replies.length, c.replyCount + added) }
      : {}),
  };
}

function insertReply(
  tree: Comment[],
  parentId: string,
  comment: Comment,
): Comment[] {
  return findAndPatch(
    tree,
    (c) => c.id === parentId,
    (c) => withReplyCount(c, [...(c.replies ?? []), comment], 1),
  );
}

/** The comments of `incoming` that are not in `tree` yet (also drops duplicates inside `incoming`). */
function fresh(tree: Comment[], incoming: Comment[]): Comment[] {
  const seen = new Set<string>();
  const out: Comment[] = [];
  for (const c of incoming) {
    if (seen.has(c.id) || containsId(tree, c.id)) continue;
    seen.add(c.id);
    out.push(c);
  }
  return out;
}

/** `real` takes the place of `previous`, keeping the replies `previous` collected. */
function takePlace(previous: Comment, real: Comment): Comment {
  const replies =
    real.replies && real.replies.length > 0 ? real.replies : previous.replies ?? real.replies;
  return replies === real.replies ? real : { ...real, replies };
}

function insertAt<T>(list: T[], item: T, index: number): T[] {
  const at = Math.max(0, Math.min(index, list.length));
  return [...list.slice(0, at), item, ...list.slice(at)];
}

// ─── Reducer ─────────────────────────────────────────────────────────────────

/**
 * Pure reducer — exported for hosts driving their own state. Idempotent: adding, appending or
 * delivering a comment whose id is already in the tree changes nothing (the same array comes
 * back), so a server echo of your own post can never produce a second copy.
 */
export function commentReducer(
  state: Comment[],
  action: CommentLocalAction,
): Comment[] {
  switch (action.kind) {
    case "add":
      if (containsId(state, action.comment.id)) return state;
      if (action.parentId) {
        return insertReply(state, action.parentId, action.comment);
      }
      // Head insertion for top-level (newest first; pairs with load-older at bottom).
      return [action.comment, ...state];

    case "swap-temp": {
      // The echo of your own post won the race: the real comment is already here.
      if (action.real.id !== action.tempId && containsId(state, action.real.id)) {
        return pruneById(state, action.tempId);
      }
      return findAndPatch(
        state,
        (c) => c.id === action.tempId,
        (c) => takePlace(c, action.real),
      );
    }

    case "remove":
      return pruneById(state, action.commentId);

    case "like-toggle":
      return findAndPatch(
        state,
        (c) => c.id === action.commentId,
        (c) => {
          if ((c.isLiked ?? false) === action.nextLiked) return c; // idempotent
          return {
            ...c,
            isLiked: action.nextLiked,
            likes:
              c.likes === null
                ? null
                : action.nextLiked
                  ? c.likes + 1
                  : Math.max(0, c.likes - 1),
          };
        },
      );

    case "like-set":
      return findAndPatch(
        state,
        (c) => c.id === action.commentId,
        (c) =>
          c.isLiked === action.liked && c.likes === action.likes
            ? c
            : { ...c, isLiked: action.liked, likes: action.likes },
      );

    case "patch-content":
      return findAndPatch(
        state,
        (c) => c.id === action.commentId,
        (c) => ({ ...c, content: action.content }),
      );

    case "patch":
      return findAndPatch(
        state,
        (c) => c.id === action.commentId,
        (c) => ({ ...c, ...action.patch, id: c.id, replies: c.replies }),
      );

    case "restore": {
      if (containsId(state, action.comment.id)) return state;
      if (!action.parentId) return insertAt(state, action.comment, action.index);
      return findAndPatch(
        state,
        (c) => c.id === action.parentId,
        (c) => withReplyCount(c, insertAt(c.replies ?? [], action.comment, action.index), 1),
      );
    }

    case "append-replies": {
      const incoming = fresh(state, action.comments);
      if (incoming.length === 0) return state;
      return findAndPatch(
        state,
        (c) => c.id === action.parentId,
        (c) => withReplyCount(c, [...(c.replies ?? []), ...incoming], 0),
      );
    }

    case "subscribe-delta": {
      const d = action.delta;
      switch (d.kind) {
        case "added": {
          if (containsId(state, d.comment.id)) return state;
          // Your own post echoed back before `onAddComment` resolved: it replaces the pending
          // comment that carries the same client id instead of becoming a second copy.
          const clientId = d.comment.clientId;
          if (clientId !== undefined && hasClientId(state, clientId)) {
            return findAndPatch(
              state,
              (c) => c.clientId === clientId,
              (c) => takePlace(c, d.comment),
            );
          }
          return d.parentId
            ? insertReply(state, d.parentId, d.comment)
            : [d.comment, ...state];
        }
        case "edited":
          return findAndPatch(
            state,
            (c) => c.id === d.commentId,
            (c) => ({ ...c, content: d.content, edited: true }),
          );
        case "removed":
          return pruneById(state, d.commentId);
        case "liked":
          return findAndPatch(
            state,
            (c) => c.id === d.commentId,
            (c) => ({ ...c, isLiked: d.liked, likes: d.count }),
          );
        case "state":
          return findAndPatch(
            state,
            (c) => c.id === d.commentId,
            (c) => (c.state === d.state ? c : { ...c, state: d.state }),
          );
        case "reacted":
          return findAndPatch(
            state,
            (c) => c.id === d.commentId,
            (c) => ({ ...c, reactions: d.reactions }),
          );
      }
      return state;
    }

    case "append-page": {
      const incoming = fresh(state, action.comments);
      return incoming.length === 0 ? state : [...state, ...incoming];
    }

    case "reset":
      return action.next;
  }
}

// ─── Hook ────────────────────────────────────────────────────────────────────

export interface UseCommentStateOptions {
  /** Captured ON MOUNT only — subsequent prop changes are ignored. */
  initialComments: Comment[];
  subscribe?: Subscribe<CommentDelta>;
  onSubscribeDelta?: (delta: CommentDelta) => void;
}

export interface UseCommentStateResult {
  comments: Comment[];
  dispatch: React.Dispatch<CommentLocalAction>;
}

/**
 * Wires:
 *  - useReducer over commentReducer
 *  - subscription effect that fires onSubscribeDelta and patches state
 *
 * onSubscribeDelta is mirrored to a ref so the subscription effect re-runs
 * ONLY on `subscribe` identity change — same shape as engagement-bar.
 */
export function useCommentState(
  opts: UseCommentStateOptions,
): UseCommentStateResult {
  const [comments, dispatch] = useReducer(
    commentReducer,
    opts.initialComments,
  );

  const onSubscribeDeltaRef = useRef(opts.onSubscribeDelta);
  useEffect(() => {
    onSubscribeDeltaRef.current = opts.onSubscribeDelta;
  });

  const subscribe = opts.subscribe;
  useEffect(() => {
    if (!subscribe) return;
    const unsub = subscribe((delta) => {
      onSubscribeDeltaRef.current?.(delta);
      dispatch({ kind: "subscribe-delta", delta });
    });
    return unsub;
  }, [subscribe]);

  return { comments, dispatch };
}

"use client";

import { useLayoutEffect, useRef } from "react";

export interface UseAutosizeTextareaOptions {
  minRows?: number;
  maxRows?: number;
}

/**
 * Resizes a <textarea> to fit its content within [minRows, maxRows] line bounds.
 * Pure DOM mutation in useLayoutEffect — no React state, no rerender.
 *
 * Returns a ref to attach to the textarea element.
 */
export function useAutosizeTextarea(
  value: string,
  opts: UseAutosizeTextareaOptions = {},
) {
  const { minRows = 1, maxRows = 6 } = opts;
  const ref = useRef<HTMLTextAreaElement | null>(null);

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    // Reset to "auto" so scrollHeight reflects natural content height.
    el.style.height = "auto";
    const computed = window.getComputedStyle(el);
    const lineHeight = parseFloat(computed.lineHeight) || 20;
    const paddingY =
      parseFloat(computed.paddingTop) + parseFloat(computed.paddingBottom);
    const min = lineHeight * minRows + paddingY;
    const max = lineHeight * maxRows + paddingY;
    const next = Math.min(Math.max(el.scrollHeight, min), max);
    el.style.height = `${next}px`;
    // Allow internal scroll only if natural height exceeds maxRows.
    el.style.overflowY = el.scrollHeight > max ? "auto" : "hidden";
  }, [value, minRows, maxRows]);

  return ref;
}

/** Coerces Date | string | number into a Date — matches event-card / progress-timeline. */
export function toDate(value: Date | string | number): Date {
  if (value instanceof Date) return value;
  return new Date(value);
}

/**
 * A valid BCP 47 tag for `locale`, else `"en"`. An invalid tag (`"en_US"` from an i18n library)
 * makes `Intl` throw, and that must not take down the render.
 */
export function resolveLocale(locale: string | undefined): string {
  if (!locale) return "en";
  try {
    return Intl.getCanonicalLocales(locale)[0] ?? "en";
  } catch {
    return "en";
  }
}

/** A valid IANA time zone, else `undefined` (the runtime's). */
function resolveTimeZone(timeZone: string | undefined): string | undefined {
  if (!timeZone) return undefined;
  try {
    new Intl.DateTimeFormat("en", { timeZone });
    return timeZone;
  } catch {
    return undefined;
  }
}

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

/** The English formatter. `now` is required here: nothing in this file reads the clock. */
function formatEnglish(date: Date, now: Date): string {
  if (Number.isNaN(date.getTime())) return "";
  const diffSec = Math.floor((now.getTime() - date.getTime()) / 1000);
  // A future date (a poll's closing time) reads "in 3d", never "Just now".
  if (diffSec <= -60) return formatIntl("en", undefined)(date, now);
  if (diffSec < 60) return "Just now";

  const diffMin = Math.floor(diffSec / 60);
  if (diffMin < 60) return `${diffMin}m`;

  const diffHr = Math.floor(diffMin / 60);
  if (diffHr < 24) return `${diffHr}h`;

  const diffDay = Math.floor(diffHr / 24);
  if (diffDay < 7) return `${diffDay}d`;

  const diffWk = Math.floor(diffDay / 7);
  if (diffWk < 5) return `${diffWk}w`;

  const sameYear = date.getFullYear() === now.getFullYear();
  return sameYear
    ? `${MONTHS[date.getMonth()]} ${date.getDate()}`
    : `${MONTHS[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()}`;
}

/** The `Intl` formatter for a resolved locale / zone (past and future). */
function formatIntl(
  tag: string,
  zone: string | undefined,
): (date: Date, now: Date) => string {
  const rtf = new Intl.RelativeTimeFormat(tag, { numeric: "auto", style: "narrow" });
  const sameYearFmt = new Intl.DateTimeFormat(tag, { month: "long", day: "numeric", timeZone: zone });
  const otherYearFmt = new Intl.DateTimeFormat(tag, {
    month: "long",
    day: "numeric",
    year: "numeric",
    timeZone: zone,
  });
  const yearFmt = new Intl.DateTimeFormat(tag, { year: "numeric", timeZone: zone });
  return (date, now) => {
    if (Number.isNaN(date.getTime())) return "";
    const diffSec = Math.trunc((date.getTime() - now.getTime()) / 1000);
    const abs = Math.abs(diffSec);
    if (abs < 60) return rtf.format(0, "second");
    if (abs < 3600) return rtf.format(Math.trunc(diffSec / 60), "minute");
    if (abs < 86400) return rtf.format(Math.trunc(diffSec / 3600), "hour");
    if (abs < 7 * 86400) return rtf.format(Math.trunc(diffSec / 86400), "day");
    if (abs < 5 * 7 * 86400) return rtf.format(Math.trunc(diffSec / (7 * 86400)), "week");
    return (yearFmt.format(date) === yearFmt.format(now) ? sameYearFmt : otherYearFmt).format(date);
  };
}

/**
 * Default English relative-time formatter for comments and posts:
 *   < 1 min     → "Just now"
 *   < 60 min    → "5m"
 *   < 24 hours  → "2h"
 *   < 7 days    → "3d"
 *   < 5 weeks   → "2w"
 *   ≥ 5 weeks   → "March 5"  (or "March 5, 2025" if year differs)
 *   in the future (≥ 1 min) → "in 3d" (`Intl.RelativeTimeFormat("en", { style: "narrow" })`)
 *
 * Pass `now` explicitly; the default only serves a caller that omits it. Local-time getters
 * are used beyond five weeks — pass `createRelativeTimeFormatter("en", timeZone)` for a fixed zone.
 */
export function defaultRelativeTime(
  date: Date,
  now: Date = new Date(), // now-ok: a default only for callers that omit `now`; the thread always passes its own
): string {
  return formatEnglish(date, now);
}

/**
 * A relative-time formatter for `locale` (BCP 47; an invalid tag falls back to `"en"`) and an
 * optional IANA `timeZone` (an invalid one falls back to the runtime's).
 * - `"en"`: exactly {@link defaultRelativeTime}'s relative output; a `timeZone` only moves the absolute dates.
 * - Otherwise: `Intl.RelativeTimeFormat(locale, { numeric: "auto", style: "narrow" })` up to five
 *   weeks either way ("5 dk. önce", "in 2h"), then a long `Intl.DateTimeFormat` date (the year only
 *   when it differs from `now`'s), in `timeZone`.
 *
 * Build it once per locale / zone (memoise it) — it creates the `Intl` formatters.
 */
export function createRelativeTimeFormatter(
  locale: string | undefined = "en",
  timeZone?: string,
): (date: Date, now: Date) => string {
  const tag = resolveLocale(locale);
  const zone = resolveTimeZone(timeZone);
  if (tag === "en" && !zone) return defaultRelativeTime;
  const intl = formatIntl(tag, zone);
  if (tag !== "en") return intl;
  // English with a time zone: the zone only moves the absolute dates ("March 5"); the relative
  // text stays exactly English ("Just now" / "5m" / "2w").
  return (date, now) => {
    const diffSec = Math.floor((now.getTime() - date.getTime()) / 1000);
    if (diffSec > -60 && diffSec < 5 * 7 * 86400) return formatEnglish(date, now);
    return intl(date, now);
  };
}

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import type {
  Comment,
  CommentDelta,
  CommentErrorContext,
  CommentLocalAction,
  CommentThreadCurrentUser,
  CommentThreadProps,
  CommentsChange,
  Subscribe,
} from "../types";
import { commentReducer, useCommentState } from "./use-comment-state";
import { containsId, findComment, hasClientId } from "../lib/tree";
import { nextReactions } from "../lib/reactions";

// ─── Pending operations (the optimistic overlay) ─────────────────────────────

type PendingBody =
  | { type: "add"; comment: Comment; parentId?: string }
  | { type: "like"; commentId: string; liked: boolean }
  | { type: "react"; commentId: string; reaction: string | null }
  | { type: "delete"; commentId: string; tombstone: boolean }
  | { type: "edit"; commentId: string; content: string };
type PendingOp = PendingBody & { id: number };

/** The tree as it looks while `pending` operations are in flight. Same array when none are. */
function applyPending(base: Comment[], pending: PendingOp[]): Comment[] {
  let tree = base;
  for (const op of pending) {
    switch (op.type) {
      case "add":
        // The server's copy already arrived (an echo): the pending row has nothing left to show.
        if (op.comment.clientId !== undefined && hasClientId(tree, op.comment.clientId)) break;
        tree = commentReducer(tree, { kind: "add", comment: op.comment, parentId: op.parentId });
        break;
      case "like":
        tree = commentReducer(tree, { kind: "like-toggle", commentId: op.commentId, nextLiked: op.liked });
        break;
      case "react": {
        const target = findComment(tree, op.commentId);
        if (target) {
          tree = commentReducer(tree, {
            kind: "patch",
            commentId: op.commentId,
            patch: { reactions: nextReactions(target.reactions, op.reaction) },
          });
        }
        break;
      }
      case "delete":
        tree = commentReducer(
          tree,
          op.tombstone
            ? { kind: "patch", commentId: op.commentId, patch: { state: "deleted" } }
            : { kind: "remove", commentId: op.commentId },
        );
        break;
      case "edit":
        tree = commentReducer(tree, {
          kind: "patch",
          commentId: op.commentId,
          patch: { content: op.content, edited: true },
        });
        break;
    }
  }
  return tree;
}

const isThenable = (value: unknown): value is PromiseLike<unknown> =>
  !!value && typeof (value as { then?: unknown }).then === "function";

const isComment = (value: unknown): value is Comment =>
  !!value && typeof value === "object" && typeof (value as { id?: unknown }).id === "string";

/** Always-current value for handlers: assigned at commit, so an event handler never sees a stale render. */
function useLatest<T>(value: T) {
  const ref = useRef(value);
  useLayoutEffect(() => {
    ref.current = value;
  });
  return ref;
}

export type PendingKind = "sending" | "unconfirmed";

export interface UseCommentTreeOptions {
  comments: Comment[];
  onCommentsChange?: CommentThreadProps["onCommentsChange"];
  currentUser?: CommentThreadCurrentUser;
  subscribe?: Subscribe<CommentDelta>;
  onSubscribeDelta?: (delta: CommentDelta) => void;
  onAddComment?: CommentThreadProps["onAddComment"];
  onLikeComment?: CommentThreadProps["onLikeComment"];
  onDeleteComment?: CommentThreadProps["onDeleteComment"];
  onEditComment?: CommentThreadProps["onEditComment"];
  onReactComment?: CommentThreadProps["onReactComment"];
  onError?: CommentThreadProps["onError"];
  optimistic: boolean;
  /** `removedMode="tombstone"` with the add-on installed. */
  tombstoneOnRemove: boolean;
  warnOnce: (key: string, message: string) => void;
}

/**
 * The thread's state engine.
 *
 *  - Uncontrolled (no `onCommentsChange`): `comments` seeds a reducer once; accepted changes apply to it.
 *  - Controlled: `comments` is the tree on every render; accepted changes are REPORTED, never applied.
 *
 * Either way a change that has a promise in flight is an overlay over that tree, so a rejection just
 * drops the overlay (the like, the reaction, the deleted subtree at its position, the old content
 * all come back) and a refetch replaces stale optimism. Only the latest request per target decides.
 */
export function useCommentTree(opts: UseCommentTreeOptions) {
  const controlled = opts.onCommentsChange !== undefined;
  const { comments: localBase, dispatch: dispatchLocal } = useCommentState({
    initialComments: opts.comments,
  });
  const base = controlled ? opts.comments : localBase;

  const [pending, setPending] = useState<PendingOp[]>([]);
  const [unconfirmed, setUnconfirmed] = useState<string[]>([]);
  /** Client ids of comments this viewer posted in this session (not server-delivered pages). */
  const [localPosted, setLocalPosted] = useState<string[]>([]);
  const shown = useMemo(() => applyPending(base, pending), [base, pending]);

  const pendingMap = useMemo(() => {
    const map = new Map<string, PendingKind>();
    for (const id of unconfirmed) map.set(id, "unconfirmed");
    for (const op of pending) if (op.type === "add") map.set(op.comment.id, "sending");
    return map;
  }, [pending, unconfirmed]);

  const latest = useLatest({ ...opts, controlled, base, shown, pendingMap });

  const seq = useRef(0);
  const [settled] = useState(() => new Map<string, number>());
  const instanceId = useId();
  const clientCounter = useRef(0);

  const reportError = useCallback((error: unknown, context: CommentErrorContext) => {
    try {
      latest.current.onError?.(error, context);
    } catch (thrown) {
      // A throwing onError must not turn a handled failure into an unhandled one.
      if (process.env.NODE_ENV !== "production") console.error("CommentThread: onError threw", thrown);
    }
  }, [latest]);

  /** Run a host callback; a throw is logged, never allowed to turn a success into a failure. */
  const callHost = useCallback((name: string, fn: () => void) => {
    try {
      fn();
    } catch (thrown) {
      if (process.env.NODE_ENV !== "production") console.error(`CommentThread: ${name} threw`, thrown);
    }
  }, []);

  /**
   * The working tree: the base as every accepted change so far has left it, advanced
   * synchronously so two changes in one tick build on each other (the rendered base only
   * catches up on the next commit). Re-synced to the rendered base on every commit and, when
   * the host ignores a report, one task later.
   */
  const work = useRef<Comment[]>(base);
  const resyncTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useLayoutEffect(() => {
    work.current = base;
  });
  useEffect(
    () => () => {
      if (resyncTimer.current) clearTimeout(resyncTimer.current);
    },
    [],
  );

  /** An accepted change: applied (uncontrolled) or reported with the tree it produces (controlled). */
  const accept = useCallback(
    (action: CommentLocalAction, change: CommentsChange) => {
      const l = latest.current;
      const current = work.current;
      const next = commentReducer(current, action);
      if (next === current) return;
      work.current = next;
      if (!l.controlled) {
        dispatchLocal(action);
        return;
      }
      if (!resyncTimer.current) {
        resyncTimer.current = setTimeout(() => {
          resyncTimer.current = null;
          work.current = latest.current.base;
        }, 0);
      }
      callHost("onCommentsChange", () => l.onCommentsChange?.(next, change));
    },
    [latest, dispatchLocal, callHost],
  );

  const removeOp = useCallback((id: number) => {
    setPending((list) => (list.some((op) => op.id === id) ? list.filter((op) => op.id !== id) : list));
  }, []);

  /** Apply `commit` unless a newer request on the same target was already applied (latest wins). */
  const settle = useCallback(
    (key: string, id: number, commit: () => void) => {
      if (id <= (settled.get(key) ?? 0)) return;
      settled.set(key, id);
      commit();
    },
    [settled],
  );

  /** Run one handler call: overlay while a promise is in flight, accept when it settles. */
  const run = useCallback(
    (m: {
      key: string;
      overlay: PendingBody;
      invoke: () => unknown;
      commit: () => void;
      context: CommentErrorContext;
    }) => {
      const id = ++seq.current;
      let result: unknown;
      try {
        result = m.invoke();
      } catch (error) {
        reportError(error, m.context);
        return;
      }
      if (!isThenable(result)) {
        settle(m.key, id, m.commit);
        return;
      }
      if (latest.current.optimistic) setPending((list) => [...list, { ...m.overlay, id } as PendingOp]);
      result.then(
        () => {
          removeOp(id);
          settle(m.key, id, m.commit);
        },
        (error: unknown) => {
          removeOp(id);
          reportError(error, m.context);
        },
      );
    },
    [latest, reportError, removeOp, settle],
  );

  const isPendingId = useCallback((id: string) => latest.current.pendingMap.has(id), [latest]);

  const like = useCallback(
    (commentId: string, nextLiked: boolean) => {
      if (isPendingId(commentId)) return;
      run({
        key: `like:${commentId}`,
        overlay: { type: "like", commentId, liked: nextLiked },
        invoke: () => latest.current.onLikeComment?.(commentId, nextLiked),
        commit: () =>
          accept({ kind: "like-toggle", commentId, nextLiked }, { kind: "liked", commentId, liked: nextLiked }),
        context: { kind: "like", commentId },
      });
    },
    [accept, isPendingId, latest, run],
  );

  const react = useCallback(
    (commentId: string, reaction: string | null) => {
      if (isPendingId(commentId)) return;
      run({
        key: `react:${commentId}`,
        overlay: { type: "react", commentId, reaction },
        invoke: () => latest.current.onReactComment?.(commentId, reaction),
        commit: () => {
          const target = findComment(work.current, commentId);
          if (!target) return;
          accept(
            { kind: "patch", commentId, patch: { reactions: nextReactions(target.reactions, reaction) } },
            { kind: "reacted", commentId, reaction },
          );
        },
        context: { kind: "react", commentId },
      });
    },
    [accept, isPendingId, latest, run, work],
  );

  const remove = useCallback(
    (commentId: string) => {
      if (isPendingId(commentId)) return;
      const tombstone = latest.current.tombstoneOnRemove;
      run({
        key: `delete:${commentId}`,
        overlay: { type: "delete", commentId, tombstone },
        invoke: () => latest.current.onDeleteComment?.(commentId),
        commit: () =>
          accept(
            tombstone
              ? { kind: "patch", commentId, patch: { state: "deleted" } }
              : { kind: "remove", commentId },
            { kind: "deleted", commentId },
          ),
        context: { kind: "delete", commentId },
      });
    },
    [accept, isPendingId, latest, run],
  );

  /** Save an edit. Resolves on success; rejects (after the rollback and `onError`) so the editor can say so. */
  const edit = useCallback(
    async (commentId: string, content: string): Promise<void> => {
      const l = latest.current;
      if (!l.onEditComment || isPendingId(commentId)) return;
      const id = ++seq.current;
      const key = `edit:${commentId}`;
      const context: CommentErrorContext = { kind: "edit", commentId };
      const commit = (result: unknown) => {
        const server = isComment(result) ? result : undefined;
        accept(
          {
            kind: "patch",
            commentId,
            patch: server
              ? { ...server, content: server.content, edited: server.edited ?? true }
              : { content, edited: true },
          },
          { kind: "edited", commentId, content: server?.content ?? content },
        );
      };
      let result: unknown;
      try {
        result = l.onEditComment(commentId, content);
        if (!isThenable(result)) {
          settle(key, id, () => commit(result));
          return;
        }
        if (l.optimistic) {
          setPending((list) => [...list, { id, type: "edit", commentId, content }]);
        }
        const value = await result;
        removeOp(id);
        settle(key, id, () => commit(value));
      } catch (error) {
        removeOp(id);
        reportError(error, context);
        throw error;
      }
    },
    [accept, isPendingId, latest, removeOp, reportError, settle],
  );

  /**
   * Post a comment (or a reply under `parentId`). Resolves when it is accepted; rejects (after the
   * rollback and `onError`) so the composer keeps the text and shows the failure.
   */
  const post = useCallback(
    async (content: string, parentId?: string): Promise<void> => {
      const l = latest.current;
      const user = l.currentUser;
      if (!user) return;
      const clientId =
        typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
          ? crypto.randomUUID()
          : `${instanceId}-${++clientCounter.current}`;
      const tempId = `temp-${clientId}`;
      const temp: Comment = {
        id: tempId,
        clientId,
        author: { id: user.id, name: user.name, avatar: user.avatar },
        content,
        createdAt: new Date(),
        likes: 0,
        isLiked: false,
        replies: [],
      };
      const id = ++seq.current;
      if (l.optimistic) setPending((list) => [...list, { id, type: "add", comment: temp, parentId }]);
      let result: Comment | void | undefined;
      try {
        result = await l.onAddComment?.(content, parentId, { clientId });
      } catch (error) {
        removeOp(id);
        reportError(error, { kind: "add", commentId: tempId, parentId });
        throw error;
      }
      removeOp(id);
      setLocalPosted((list) => [...list, clientId, ...(isComment(result) ? [result.id] : [])]);
      if (isComment(result)) {
        accept({ kind: "add", comment: result, parentId }, { kind: "added", comment: result, parentId });
      } else if (!latest.current.onAddComment) {
        // No handler: a local-only thread. The posted comment is a normal comment.
        accept({ kind: "add", comment: temp, parentId }, { kind: "added", comment: temp, parentId });
      } else if (!latest.current.controlled && latest.current.optimistic) {
        // Nothing came back: the pending comment stays (its actions off) until a delta or reset
        // brings the real one. Controlled, the prop is the truth, so nothing stays. If the
        // server's echo already landed (same client id), there is nothing left to keep.
        if (!hasClientId(work.current, clientId) && !containsId(work.current, tempId)) {
          accept({ kind: "add", comment: temp, parentId }, { kind: "added", comment: temp, parentId });
          setUnconfirmed((list) => [...list, tempId]);
        }
      }
    },
    [accept, instanceId, latest, removeOp, reportError, work],
  );

  // ─── Realtime ──────────────────────────────────────────────────────────────

  const applyDelta = useCallback(
    (delta: CommentDelta) => {
      const l = latest.current;
      let d = delta;
      if (d.kind === "removed" && l.tombstoneOnRemove) {
        d = { kind: "state", commentId: d.commentId, state: "removed" };
      }
      if (d.kind === "added" && d.parentId && !containsId(work.current, d.parentId)) {
        l.warnOnce(
          "unknown-parent",
          `CommentThread: an "added" delta names parentId "${d.parentId}", which is not in the thread. The comment was dropped.`,
        );
        return;
      }
      accept({ kind: "subscribe-delta", delta: d }, { kind: "delta", delta: d });
    },
    [accept, latest, work],
  );

  const subscribe = opts.subscribe;
  useEffect(() => {
    if (!subscribe) return;
    return subscribe((delta) => {
      callHost("onSubscribeDelta", () => latest.current.onSubscribeDelta?.(delta));
      applyDelta(delta);
    });
  }, [subscribe, applyDelta, latest, callHost]);

  /** Handle `dispatch` / `reset`: applied (uncontrolled) or reported (controlled). */
  const dispatch = useCallback(
    (action: CommentLocalAction) => accept(action, { kind: "dispatch", action }),
    [accept],
  );

  return {
    controlled,
    comments: shown,
    pendingMap,
    like,
    react,
    remove,
    edit,
    post,
    accept,
    dispatch,
    reportError,
    localPosted,
    work,
    isPending: isPendingId,
  };
}

"use client";

import { useCallback, useLayoutEffect, useRef, useState } from "react";
import type {
  Comment,
  CommentErrorContext,
  CommentLocalAction,
  CommentPage,
  CommentsChange,
} from "../types";
import { findComment } from "../lib/tree";

/** Loading state of one comment's replies. Absent = nothing requested yet. */
export interface ReplyLoad {
  loading: boolean;
  failed: boolean;
  /** Cursor for the next page. */
  cursor: string | null;
  /** Are more replies waiting on the server? */
  hasMore: boolean;
  /** The comment's `repliesCursor` when this was recorded; a different one makes it stale. */
  seed: string | null;
}

export interface UsePagingOptions {
  /** The shown tree (for the top-level count and reply lookups). */
  comments: Comment[];
  /** Accept loaded items: applied (uncontrolled) or reported (controlled). */
  accept: (action: CommentLocalAction, change: CommentsChange) => void;
  reportError: (error: unknown, context: CommentErrorContext) => void;
  onLoadMore?: (page: number) => Promise<Comment[]>;
  onLoadMoreCursor?: (cursor: string | null) => Promise<CommentPage>;
  onLoadReplies?: (commentId: string, cursor: string | null) => Promise<CommentPage>;
  pageSize: number;
  hasMore?: boolean;
  nextCursor?: string | null;
  /** Comments the viewer posted in this session (or still pending): not counted by the legacy heuristic. */
  isLocal: (comment: Comment) => boolean;
}

/** Top-level paging ("Load more") and per-comment reply loading. All state lives in the thread instance. */
export function usePaging(opts: UsePagingOptions) {
  const latest = useRef(opts);
  useLayoutEffect(() => {
    latest.current = opts;
  });

  // ─── Top level ──────────────────────────────────────────────────────────────
  const [loading, setLoading] = useState(false);
  const [failed, setFailed] = useState(false);
  const epoch = useRef(0);
  const loadingRef = useRef(false);
  const loadedRef = useRef<{ cursor: string | null; hasMore: boolean } | null>(null);
  const lastPageRef = useRef(1);
  const [lastPageFull, setLastPageFull] = useState(true);
  const [loaded, setLoaded] = useState<{ cursor: string | null; hasMore: boolean } | null>(null);

  const topCount = opts.comments.filter((c) => !opts.isLocal(c)).length;
  const loader = opts.onLoadMoreCursor ?? opts.onLoadMore;

  let hasMore: boolean;
  if (opts.hasMore !== undefined) hasMore = opts.hasMore;
  else if (opts.onLoadMoreCursor) {
    if (opts.nextCursor !== undefined) hasMore = opts.nextCursor !== null;
    else if (loaded) hasMore = loaded.hasMore;
    else hasMore = topCount >= opts.pageSize;
  } else hasMore = topCount >= opts.pageSize && lastPageFull;

  const loadMore = useCallback(async () => {
    const l = latest.current;
    if (loadingRef.current || !(l.onLoadMoreCursor ?? l.onLoadMore)) return;
    loadingRef.current = true;
    const started = epoch.current;
    setLoading(true);
    setFailed(false);
    try {
      if (l.onLoadMoreCursor) {
        const cursor = l.nextCursor !== undefined ? l.nextCursor : (loadedRef.current?.cursor ?? null);
        const page = await l.onLoadMoreCursor(cursor);
        if (started !== epoch.current) return; // a reset happened meanwhile: stale
        const items = page.items ?? [];
        l.accept({ kind: "append-page", comments: items }, { kind: "page", comments: items });
        const next = page.nextCursor ?? null;
        const state = { cursor: next, hasMore: page.hasMore ?? next !== null };
        loadedRef.current = state;
        setLoaded(state);
      } else if (l.onLoadMore) {
        const nextPage = lastPageRef.current + 1;
        const items = (await l.onLoadMore(nextPage)) ?? [];
        if (started !== epoch.current) return;
        l.accept({ kind: "append-page", comments: items }, { kind: "page", comments: items });
        lastPageRef.current = nextPage;
        setLastPageFull(items.length >= l.pageSize);
      }
    } catch (error) {
      if (started !== epoch.current) return;
      setFailed(true);
      l.reportError(error, { kind: "load-more" });
    } finally {
      if (started === epoch.current) {
        loadingRef.current = false;
        setLoading(false);
      }
    }
  }, []);

  // ─── Replies ────────────────────────────────────────────────────────────────
  const [replyLoads, setReplyLoads] = useState<Record<string, ReplyLoad>>({});
  const replyLoadsRef = useRef<Record<string, ReplyLoad>>({});
  const [inflight] = useState(() => new Set<string>());

  const loadReplies = useCallback(async (commentId: string) => {
    const l = latest.current;
    const fetchPage = l.onLoadReplies;
    if (!fetchPage || inflight.has(commentId)) return;
    inflight.add(commentId);
    const started = epoch.current;
    const comment = findComment(l.comments, commentId);
    const seed = comment?.repliesCursor ?? null;
    const found = replyLoadsRef.current[commentId];
    const previous = found && found.seed === seed ? found : undefined;
    const cursor = previous ? previous.cursor : seed;
    const set = (value: ReplyLoad) => {
      if (started !== epoch.current) return;
      replyLoadsRef.current = { ...replyLoadsRef.current, [commentId]: value };
      setReplyLoads(replyLoadsRef.current);
    };
    set({ loading: true, failed: false, cursor, hasMore: previous?.hasMore ?? true, seed });
    try {
      const page = await fetchPage(commentId, cursor);
      if (started !== epoch.current) return;
      const items = page.items ?? [];
      l.accept(
        { kind: "append-replies", parentId: commentId, comments: items },
        { kind: "replies", parentId: commentId, comments: items },
      );
      const next = page.nextCursor ?? null;
      set({ loading: false, failed: false, cursor: next, hasMore: page.hasMore ?? next !== null, seed });
    } catch (error) {
      set({ loading: false, failed: true, cursor, hasMore: previous?.hasMore ?? true, seed });
      if (started === epoch.current) l.reportError(error, { kind: "load-replies", commentId, parentId: commentId });
    } finally {
      if (started === epoch.current) inflight.delete(commentId);
    }
  }, [inflight]);

  /** The tree was replaced (handle.reset): forget paging and reply state, drop loads still in flight. */
  const reset = useCallback(() => {
    epoch.current++;
    loadingRef.current = false;
    loadedRef.current = null;
    lastPageRef.current = 1;
    inflight.clear();
    replyLoadsRef.current = {};
    setLoading(false);
    setFailed(false);
    setLastPageFull(true);
    setLoaded(null);
    setReplyLoads({});
  }, [inflight]);

  return {
    reset,
    hasMore: !!loader && hasMore,
    loadingMore: loading,
    loadMoreFailed: failed,
    loadMore,
    replyLoads,
    loadReplies,
  };
}

