import { createContext, useContext } from "react";
import type { CommentModerationExtension } from "../types";

/**
 * Moderation injection seam (feature-slicing, injection surface). The base never imports
 * `features/moderation/**`: a consumer wires inline edit, tombstones and the pinned marker in by
 * passing `moderation={commentModeration}` (registry item `@ilinxa/comment-thread-moderation`, imported from
 * `@/components/comment-thread/features/moderation`), or their own
 * implementation of {@link CommentModerationExtension}). The thread publishes that value here so
 * every row reads it without prop drilling.
 */
export const CommentModerationContext =
  createContext<CommentModerationExtension | null>(null);

/** Null when no `moderation` extension is wired. */
export function useCommentModerationOptional(): CommentModerationExtension | null {
  return useContext(CommentModerationContext);
}

import {
  defaultCommentThreadLabels,
  type CommentThreadLabels,
  type ResolvedCommentThreadLabels,
} from "../types";

/** Merge a partial `labels` over the defaults; an explicit `undefined` keeps the default. */
export function resolveLabels(
  labels: CommentThreadLabels | undefined,
): ResolvedCommentThreadLabels {
  const out: ResolvedCommentThreadLabels = { ...defaultCommentThreadLabels };
  if (!labels) return out;
  const target = out as unknown as Record<string, unknown>;
  for (const [key, value] of Object.entries(labels)) {
    if (key === "formatRelativeTime") continue; // a formatter, not a string
    if (value !== undefined) target[key] = value;
  }
  // The rows' like / unlike names: an explicit thread label, else the nested engagement one,
  // else the default — so `labels.engagement.like` alone localizes the heart.
  if (labels.like === undefined && labels.engagement?.like !== undefined) out.like = labels.engagement.like;
  if (labels.unlike === undefined && labels.engagement?.unlike !== undefined) {
    out.unlike = labels.engagement.unlike;
  }
  return out;
}

import type { Comment } from "../types";

/** Is a comment with this id anywhere in the tree? */
export function containsId(tree: Comment[], id: string): boolean {
  for (const c of tree) {
    if (c.id === id) return true;
    if (c.replies && c.replies.length > 0 && containsId(c.replies, id)) return true;
  }
  return false;
}

/** The comment with this id, wherever it sits in the tree. */
export function findComment(tree: Comment[], id: string): Comment | undefined {
  for (const c of tree) {
    if (c.id === id) return c;
    if (c.replies && c.replies.length > 0) {
      const hit = findComment(c.replies, id);
      if (hit) return hit;
    }
  }
  return undefined;
}

/** Does any comment in the tree carry this client id? */
export function hasClientId(tree: Comment[], clientId: string): boolean {
  for (const c of tree) {
    if (c.clientId === clientId) return true;
    if (c.replies && c.replies.length > 0 && hasClientId(c.replies, clientId)) return true;
  }
  return false;
}

/** `true` for a comment that renders normally (no `state`, or `"visible"`). */
export function isVisibleState(comment: Comment): boolean {
  return comment.state === undefined || comment.state === "visible";
}

/** Does the tree hold a comment whose state is not `"visible"`? */
export function hasNonVisible(tree: Comment[]): boolean {
  for (const c of tree) {
    if (!isVisibleState(c)) return true;
    if (c.replies && c.replies.length > 0 && hasNonVisible(c.replies)) return true;
  }
  return false;
}

import type {
  Comment,
  CommentThreadCurrentUser,
  ResolvedCommentPermissions,
} from "../types";

/**
 * A comment's permissions: its own `permissions` over the thread defaults (each DEFINED key
 * wins). Defaults: delete / edit = the viewer wrote it; reply = signed in; react = true;
 * report = the viewer did not write it; pin / hide = false.
 */
export function resolvePermissions(
  comment: Comment,
  currentUser: CommentThreadCurrentUser | undefined,
): ResolvedCommentPermissions {
  const isOwn = !!currentUser && currentUser.id === comment.author.id;
  const own = comment.permissions;
  return {
    canEdit: own?.canEdit ?? isOwn,
    canDelete: own?.canDelete ?? isOwn,
    canPin: own?.canPin ?? false,
    canHide: own?.canHide ?? false,
    canReply: own?.canReply ?? !!currentUser,
    canReact: own?.canReact ?? true,
    canReport: own?.canReport ?? !isOwn,
  };
}

import type { CommentReactions } from "../types";

const bump = (n: number | null | undefined, by: number): number | null | undefined =>
  typeof n === "number" ? Math.max(0, n + by) : n;

/**
 * The reaction data after the viewer picks `next` (or clears it with `null`). Withheld tallies
 * (`null` / missing) stay withheld: only numbers move.
 */
export function nextReactions(
  current: CommentReactions | undefined,
  next: string | null,
): CommentReactions {
  const previous = current?.viewerReaction ?? null;
  if (previous === next) return { ...current, viewerReaction: next };
  const counts: Record<string, number | null> = { ...current?.counts };
  if (previous !== null && previous in counts) counts[previous] = bump(counts[previous], -1) ?? null;
  if (next !== null && next in counts) counts[next] = bump(counts[next], 1) ?? null;
  const total = current?.totalCount;
  const delta = (next !== null ? 1 : 0) - (previous !== null ? 1 : 0);
  return {
    ...current,
    viewerReaction: next,
    counts,
    totalCount: delta === 0 ? total : bump(total, delta),
  };
}

import type {
  Comment,
  CommentActionHelpers,
  CommentMenuItem,
  ResolvedCommentThreadLabels,
} from "../types";

export interface BuildMenuItemsArgs {
  comment: Comment;
  helpers: CommentActionHelpers;
  labels: ResolvedCommentThreadLabels;
  /** `onReportComment` is wired. */
  hasReport: boolean;
  /** `onEditComment` is wired AND the moderation add-on is installed. */
  canEditAtAll: boolean;
  onEdit: () => void;
  onDelete: () => void;
  onReport: () => void;
  commentActions?: (comment: Comment, helpers: CommentActionHelpers) => CommentMenuItem[];
  extraActions?: (comment: Comment, helpers: CommentActionHelpers) => CommentMenuItem[];
}

/**
 * The kebab's items: `commentActions` takes over entirely; otherwise the permitted defaults
 * (Edit, Report, Delete) followed by `extraActions`. Items of a pending comment are off.
 */
export function buildMenuItems(a: BuildMenuItemsArgs): CommentMenuItem[] {
  if (a.commentActions) return a.commentActions(a.comment, a.helpers);
  const { permissions, isPending } = a.helpers;
  const items: CommentMenuItem[] = [];
  if (a.canEditAtAll && permissions.canEdit && !isPending) {
    items.push({ label: a.labels.edit, onClick: a.onEdit });
  }
  if (a.hasReport && permissions.canReport) {
    items.push({ label: a.labels.report, onClick: a.onReport, disabled: isPending });
  }
  if (permissions.canDelete) {
    items.push({
      label: a.labels.delete,
      destructive: true,
      onClick: a.onDelete,
      disabled: isPending,
    });
  }
  if (a.extraActions) items.push(...a.extraActions(a.comment, a.helpers));
  return items;
}

